1	package world
2	
3	import (
4		"fmt"
5		"math"
6	)
7	
8	// NameMapping 描述旧规则中一个名称到新规则名称的显式转换关系。
9	//
10	// From 必须是来源记录旧规则中存在的地点或物品种类，To 必须是目标规则中
11	// 存在的对应名称；空名称、来源不存在于旧规则或目标不存在于新规则都在
12	// 预览时返回规则错误。
13	type NameMapping struct {
14		// From 是旧规则中的地点或物品种类名称。
15		From string
16		// To 是新规则中的对应名称。
17		To string
18	}
19	
20	// MigrationPreview 是把槽当前最新记录按对应关系显式迁移到目标规则的
21	// 预览结果。
22	//
23	// 预览只读：返回所依据的来源记录标识、旧新版本、按对应关系转换后的完整
24	// 世界状态（深拷贝）以及是否可提交。它不改变槽指向、历史或任何记录文件；
25	// 修改返回的状态也不影响存档。
26	type MigrationPreview struct {
27		// RecordID 是所依据的来源记录标识（槽当前最新记录）。
28		RecordID RecordID
29		// OldVersion 是来源记录的规则版本。
30		OldVersion string
31		// TargetVersion 是目标规则版本。
32		TargetVersion string
33		// State 是转换后的完整世界状态（深拷贝），规则已替换为目标规则。
34		// 正式迁移以排他锁下重新读取和计算的结果为准，不使用调用方可能改过
35		// 的本状态。
36		State State
37		// Committable 表示转换后的状态能否在目标规则下提交（无阻碍）。
38		Committable bool
39		// Blockers 是全部阻碍，排序与升级检查一致；重复预览输出顺序一致。
40		Blockers []Blocker
41	}
42	
43	// MigrationResult 是正式迁移的返回结果。
44	type MigrationResult struct {
45		// Preview 是对来源记录与目标规则的预览结果（排他锁下重新读取并计算）。
46		Preview MigrationPreview
47		// Record 是成功时新记录的元信息；被阻碍时为零值。
48		Record RecordInfo
49	}
50	
51	// validateMappings 校验转换对应关系：来源必须存在于旧规则，目标必须存在
52	// 于新规则，名称非空，同一来源不重复指定。即使没有角色使用这些名称也要
53	// 检查。
54	func validateMappings(old, target Rules, locations, items []NameMapping) error {
55		oldLocs := make(map[string]struct{}, len(old.Locations))
56		for _, l := range old.Locations {
57			oldLocs[l] = struct{}{}
58		}
59		newLocs := make(map[string]struct{}, len(target.Locations))
60		for _, l := range target.Locations {
61			newLocs[l] = struct{}{}
62		}
63		if err := validateMappingSet("地点", locations, oldLocs, newLocs); err != nil {
64			return err
65		}
66	
67		oldKinds := make(map[string]struct{}, len(old.ItemKinds))
68		for _, k := range old.ItemKinds {
69			oldKinds[k] = struct{}{}
70		}
71		newKinds := make(map[string]struct{}, len(target.ItemKinds))
72		for _, k := range target.ItemKinds {
73			newKinds[k] = struct{}{}
74		}
75		return validateMappingSet("物品种类", items, oldKinds, newKinds)
76	}
77	
78	func validateMappingSet(kind string, mappings []NameMapping, oldNames, newNames map[string]struct{}) error {
79		seen := make(map[string]struct{}, len(mappings))
80		for i, m := range mappings {
81			if m.From == "" {
82				return ruleErrorf("%s转换关系 %d 的来源名称为空", kind, i)
83			}
84			if m.To == "" {
85				return ruleErrorf("%s转换关系 %d 的目标名称为空", kind, i)
86			}
87			if _, ok := oldNames[m.From]; !ok {
88				return ruleErrorf("%s转换关系的来源 %q 不存在于旧规则", kind, m.From)
89			}
90			if _, ok := newNames[m.To]; !ok {
91				return ruleErrorf("%s转换关系的目标 %q 不存在于新规则", kind, m.To)
92			}
93			if _, dup := seen[m.From]; dup {
94				return ruleErrorf("%s转换关系的来源 %q 重复指定", kind, m.From)
95			}
96			seen[m.From] = struct{}{}
97		}
98		return nil
99	}
100	
101	// applyMigration 按对应关系转换状态：角色按对应关系改变所在地点（无需
102	// 符合旧道路），物品改变种类但不增减数量；多个条目转换成同一种物品时
103	// 合并数量，按原列表中首次出现的位置保留一个条目。转换只作用于原始名称
104	// 一次，不沿对应关系连续替换，因此互换名称也有确定结果。未指定的名称
105	// 保持原样。种子、时间片、角色标识及角色排列保持不变。
106	//
107	// 合并数量或携带总量超出 int 范围时返回规则错误，不回绕也不丢弃物品。
108	func applyMigration(st State, locations, items []NameMapping) (State, error) {
109		locLookup := make(map[string]string, len(locations))
110		for _, m := range locations {
111			locLookup[m.From] = m.To
112		}
113		itemLookup := make(map[string]string, len(items))
114		for _, m := range items {
115			itemLookup[m.From] = m.To
116		}
117	
118		out := cloneState(st)
119	
120		for i := range out.Characters {
121			if to, ok := locLookup[out.Characters[i].Location]; ok {
122				out.Characters[i].Location = to
123			}
124		}
125	
126		for i := range out.Characters {
127			ch := &out.Characters[i]
128			merged := make([]CharacterItem, 0, len(ch.Items))
129			indexByName := make(map[string]int, len(ch.Items))
130			for _, it := range ch.Items {
131				name := it.Item
132				if to, ok := itemLookup[name]; ok {
133					name = to
134				}
135				if idx, ok := indexByName[name]; ok {
136					sum, ok := addInt(merged[idx].Count, it.Count)
137					if !ok {
138						return State{}, ruleErrorf("角色 %q 的物品 %q 合并数量超出整数范围", ch.ID, name)
139					}
140					merged[idx].Count = sum
141				} else {
142					indexByName[name] = len(merged)
143					merged = append(merged, CharacterItem{Item: name, Count: it.Count})
144				}
145			}
146			ch.Items = merged
147	
148			// 携带总量溢出检查：各物品数量都合法，但不同物品相加可能超出
149			// int 范围，同样不能回绕或丢弃。这是显式迁移特有的整数范围门槛，
150			// 与携带上限判断不同：无论目标规则是否给该角色设置上限，真实总量
151			// 超出 int 范围都拒绝，不能因为共用总量判断而把“无上限”当成允许
152			// 溢出迁移。精确求和与其余入口共用 carryTotal，此处只保留自己的
153			// 溢出判定。
154			if carryTotal(ch.Items).Cmp(maxIntBig) > 0 {
155				return State{}, ruleErrorf("角色 %q 携带总量超出整数范围", ch.ID)
156			}
157		}
158		return out, nil
159	}
160	
161	// addInt 做一次带溢出检查的 int 加法，返回结果与是否溢出。
162	func addInt(a, b int) (int, bool) {
163		if b > 0 && a > math.MaxInt-b {
164			return 0, false
165		}
166		if b < 0 && a < math.MinInt-b {
167			return 0, false
168		}
169		return a + b, true
170	}
171	
172	// migrationComputeLocked 在调用方已持锁（共享或排他均可）的前提下读取并
173	// 校验槽当前最新记录，校验转换对应关系，计算转换后的状态与阻碍。来源
174	// 读取、完整性检查、可接受版本与版本相异判断共用
175	// sourceForTransformLocked，本函数只负责迁移自己的对应关系校验、转换与
176	// 阻碍计算。不写入。
177	func (a *Archive) migrationComputeLocked(slot string, acceptedVersions []string, target Rules, locations, items []NameMapping) (MigrationPreview, *envelope, error) {
178		latest, env, err := a.sourceForTransformLocked(slot, acceptedVersions, target.Version)
179		if err != nil {
180			return MigrationPreview{}, nil, err
181		}
182		if err := validateMappings(env.State.Rules, target, locations, items); err != nil {
183			return MigrationPreview{}, nil, err
184		}
185		transformed, err := applyMigration(env.State, locations, items)
186		if err != nil {
187			return MigrationPreview{}, nil, err
188		}
189		// 转换后的状态保存目标规则。
190		transformed.Rules = cloneRules(target)
191		blockers := checkCompatibility(transformed, target)
192		preview := MigrationPreview{
193			RecordID:      latest,
194			OldVersion:    env.State.Rules.Version,
195			TargetVersion: target.Version,
196			State:         transformed,
197			Committable:   len(blockers) == 0,
198			Blockers:      blockers,
199		}
200		return preview, env, nil
201	}
202	
203	// PreviewMigration 预览把槽当前最新记录按对应关系显式迁移到目标规则。
204	//
205	// 传入槽名、可接受的旧版本集合、目标规则，以及旧地点到新地点、旧物品到
206	// 新物品的对应关系，返回所依据的来源记录标识、旧新版本、转换后的完整
207	// 世界状态（深拷贝）及是否可提交。转换只作用于原始名称一次，不沿对应
208	// 关系连续替换；未指定的名称保持原样。转换后仍有缺失地点、不被允许的
209	// 物品或超过目标携带上限时，一次列出全部阻碍，重复预览输出顺序一致。
210	//
211	// 预览只读：不改变世界、历史或槽当前记录，修改返回的状态也不影响存档。
212	// 目标规则须满足规则自身的合法性要求且版本与来源不同；对应关系的来源
213	// 必须存在于旧规则、目标必须存在于新规则（即使没有角色使用也要检查），
214	// 空目标或未知名称返回规则错误；合并数量或携带总量超出 int 范围返回规则
215	// 错误。来源缺失、损坏或版本不被接受时沿用已有对应错误，不自动挑选历史
216	// 记录。
217	func (a *Archive) PreviewMigration(slot string, acceptedVersions []string, target Rules, locations, items []NameMapping) (MigrationPreview, error) {
218		if !validSlotName(slot) {
219			return MigrationPreview{}, &NotFoundError{Slot: slot}
220		}
221		if err := validateRules(target); err != nil {
222			return MigrationPreview{}, err
223		}
224		lock, err := acquireSharedLock(a.dir)
225		if err != nil {
226			return MigrationPreview{}, err
227		}
228		defer lock.release()
229		preview, _, err := a.migrationComputeLocked(slot, acceptedVersions, target, locations, items)
230		if err != nil {
231			return MigrationPreview{}, err
232		}
233		return preview, nil
234	}
235	
236	// Migrate 在预览后正式迁移：用目标规则与转换后的状态生成一条以来源为父
237	// 的新记录并加入本槽保存次序。
238	//
239	// 传入与预览相同的条件，并带预览返回的来源记录标识 source。提交时在
240	// 排他锁下重新读取并完整校验来源，重新校验目标规则与对应关系、重新计算
241	// 转换后的状态与阻碍，绝不使用调用方可能改过的预览状态：
242	//
243	//   - source 为空，或槽已不再指向该来源（被并发覆盖、升级、确认恢复或
244	//     另一次迁移抢先提交），返回 *ConflictError。
245	//   - 来源缺失、损坏或版本不被接受分别返回已有的不存在、损坏或版本拒绝
246	//     错误，不改选其他记录。
247	//   - 仍有阻碍时返回阻碍信息并拒绝保存，不改变当前记录或历史。
248	//
249	// 成功后产生一条以来源为父的新记录，保存目标规则与转换后的状态，加入
250	// 本槽保存次序；种子、时间片、角色标识及角色排列保持原样。与覆盖、升级、
251	// 确认恢复或另一次迁移竞争时，同一来源最多一个成功。任何拒绝都不改变
252	// 当前记录或历史；中断后重开只能看到迁移前或迁移后的完整记录与历史。
253	// 旧记录及已有分支保留原状态，恢复读取仍能找到旧版本；迁移后的记录可
254	// 继续按新规则移动、改变物品并保存，普通读取不自动转换。
255	func (a *Archive) Migrate(slot string, acceptedVersions []string, target Rules, locations, items []NameMapping, source RecordID) (MigrationResult, error) {
256		if !validSlotName(slot) {
257			return MigrationResult{}, &NotFoundError{Slot: slot}
258		}
259		if source == "" {
260			return MigrationResult{}, &ConflictError{Slot: slot, Reason: "迁移必须提供所依据的来源记录标识"}
261		}
262		if err := validateRules(target); err != nil {
263			return MigrationResult{}, err
264		}
265		lock, err := acquireLock(a.dir)
266		if err != nil {
267			return MigrationResult{}, err
268		}
269		defer lock.release()
270	
271		oldPointer, err := a.readSlotPointerLocked(slot)
272		if err != nil {
273			return MigrationResult{}, err
274		}
275		// 乐观并发控制：槽必须仍指向预览时的来源记录。
276		if oldPointer.Latest != source {
277			return MigrationResult{}, &ConflictError{
278				Slot:   slot,
279				Reason: "所依据的来源记录已不是该槽最新记录",
280			}
281		}
282	
283		// 排他锁下重新读取、校验并计算，不采信调用方带回的任何状态。
284		preview, _, err := a.migrationComputeLocked(slot, acceptedVersions, target, locations, items)
285		if err != nil {
286			return MigrationResult{}, err
287		}
288		if !preview.Committable {
289			return MigrationResult{Preview: preview}, &RuleError{
290				Reason: fmt.Sprintf("迁移被阻碍: 转换后的状态无法在目标规则下提交（%d 处阻碍）", len(preview.Blockers)),
291			}
292		}
293	
294		// 保存目标规则与排他锁下重新计算出的转换结果；以来源为父，沿用
295		// 共同的新记录组装、落盘与槽指针提交路径。记录完整落盘后才原子
296		// 更新指针：新记录前置进保存次序，旧历史原样保留。崩溃在这一步
297		// 之前时槽保持迁移前的指向与历史，新记录因不在历史索引中而不会
298		// 进入恢复候选。
299		info, err := a.appendSlotRecordLocked(slotSave{
300			slot:          slot,
301			oldPointer:    oldPointer,
302			parent:        source,
303			historyAnchor: source,
304			state:         preview.State,
305		})
306		if err != nil {
307			return MigrationResult{}, err
308		}
309		return MigrationResult{Preview: preview, Record: info}, nil
310	}
