216		}
217		lock, err := acquireLock(a.dir)
218		if err != nil {
219			return UpgradeResult{}, err
220		}
221		defer lock.release()
222	
223		oldPointer, err := a.readSlotPointerLocked(slot)
224		if err != nil {
225			return UpgradeResult{}, err
226		}
227		latest := oldPointer.Latest
228		if latest != expected {
