1	package world
2	
3	import (
4		"crypto/rand"
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"fmt"
9		"io"
10		"os"
11		"path/filepath"
12	)
13	
14	// RecordID 是一次成功保存产生的、在同一存档目录内唯一的记录标识。
15	type RecordID string
16	
17	// archiveFormatVersion 是存档目录布局版本，写入目录标记中。
18	const archiveFormatVersion = 1
19	
20	// recordFormatVersion 是当前唯一支持的记录格式版本。记录格式与存档目录
21	// 布局版本是两个独立的编号：目录可打开不代表其中每条记录都能被理解，
22	// 格式编号不是该值的记录（缺失、零、负值或其他正整数）一律按损坏处理，
23	// 即使其校验和匹配、世界状态合法。
24	const recordFormatVersion = 1
25	
26	// envelope 是记录文件在磁盘上的完整编码。
27	type envelope struct {
28		// Format 是记录格式版本。
29		Format int `json:"format"`
30		// ID 是本条记录的唯一标识。
31		ID RecordID `json:"id"`
32		// Parent 是父记录标识；直接建立的槽首条记录为空。
33		Parent RecordID `json:"parent,omitempty"`
34		// SlotFirst 标记本条记录是否为其所在槽的首条记录
35		// （直接建立的根记录，或从其他槽分出的分支记录）。
36		SlotFirst bool `json:"slotFirst"`
37		// Checksum 是对（格式版本、ID、父记录、首记录标记、完整世界状态）
38		// 计算出的内容校验和，因此父记录关系也被纳入校验。
39		Checksum string `json:"checksum"`
40		// State 是完整世界数据：种子、规则与全部状态。
41		State State `json:"state"`
42	}
43	
44	// checksumPayload 是参与校验和计算的规范内容。
45	type checksumPayload struct {
46		Format    int      `json:"format"`
47		ID        RecordID `json:"id"`
48		Parent    RecordID `json:"parent"`
49		SlotFirst bool     `json:"slotFirst"`
50		State     State    `json:"state"`
51	}
52	
53	func computeChecksum(e *envelope) string {
54		p := checksumPayload{
55			Format:    e.Format,
56			ID:        e.ID,
57			Parent:    e.Parent,
58			SlotFirst: e.SlotFirst,
59			State:     e.State,
60		}
61		// encoding/json 对 map 按键排序输出，同一状态总是得到相同字节。
62		b, _ := json.Marshal(p)
63		sum := sha256.Sum256(b)
64		return hex.EncodeToString(sum[:])
65	}
66	
67	// newRecordID 产生目录内唯一的记录标识。
68	func newRecordID() (RecordID, error) {
69		var b [16]byte
70		if _, err := rand.Read(b[:]); err != nil {
71			return "", err
72		}
73		return RecordID("r" + hex.EncodeToString(b[:])), nil
74	}
75	
76	func recordPath(dir string, id RecordID) string {
77		return filepath.Join(dir, "records", string(id)+".json")
78	}
79	
80	// writeRecord 将一条记录以“先临时文件后原子改名”的方式落盘，
81	// 并校验目标文件名此前不存在，保证记录标识不会复用或混写。
82	func writeRecord(slotDir string, e *envelope) error {
83		final := recordPath(slotDir, e.ID)
84		data, err := json.MarshalIndent(e, "", "  ")
85		if err != nil {
86			return err
87		}
88	
89		// O_EXCL：即便极小概率撞到重复 ID，也绝不会覆盖别的记录。
90		f, err := os.OpenFile(final+".tmp",
91			os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
92		if err != nil {
93			return err
94		}
95		tmpName := f.Name()
96		clean := true
97		defer func() {
98			if clean {
99				os.Remove(tmpName)
100			}
101		}()
102	
103		if _, err := f.Write(data); err != nil {
104			f.Close()
105			return err
106		}
107		if err := f.Sync(); err != nil {
108			f.Close()
109			return err
110		}
111		if err := f.Close(); err != nil {
112			return err
113		}
114		if err := os.Rename(tmpName, final); err != nil {
115			return err
116		}
117		clean = false
118		if err := syncDir(filepath.Dir(final)); err != nil {
119			return err
120		}
121		return nil
122	}
123	
124	// loadRecord 读取并解析一条记录文件，但不做校验。
125	func loadRecord(path string) (*envelope, error) {
126		f, err := os.Open(path)
127		if err != nil {
128			return nil, err
129		}
130		defer f.Close()
131		data, err := io.ReadAll(f)
132		if err != nil {
133			return nil, err
134		}
135		var e envelope
136		if err := json.Unmarshal(data, &e); err != nil {
137			return nil, fmt.Errorf("记录无法解析: %w", err)
138		}
139		return &e, nil
140	}
141	
142	func syncDir(dir string) error {
143		d, err := os.Open(dir)
144		if err != nil {
145			return err
146		}
147		defer d.Close()
148		return d.Sync()
149	}
150	
151	// writeAtomic 把 data 写入 dir 下的 name：同目录临时文件、fsync、
152	// 原子改名，保证崩溃后只会看到旧文件或新文件。
153	func writeAtomic(dir, name string, data []byte) error {
154		tmp := filepath.Join(dir, ".tmp-"+name+"-"+randomSuffix())
155		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
156		if err != nil {
157			return err
158		}
159		clean := true
160		defer func() {
161			if clean {
162				os.Remove(tmp)
163			}
164		}()
165		if _, err := f.Write(data); err != nil {
166			f.Close()
167			return err
168		}
169		if err := f.Sync(); err != nil {
170			f.Close()
171			return err
172		}
173		if err := f.Close(); err != nil {
174			return err
175		}
176		final := filepath.Join(dir, name)
177		if err := os.Rename(tmp, final); err != nil {
178			return err
179		}
180		clean = false
181		return syncDir(dir)
182	}
183	
184	func randomSuffix() string {
185		var b [8]byte
186		_, _ = rand.Read(b[:])
187		return hex.EncodeToString(b[:])
188	}
189

